    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
    colors={grid[r][c] for r,c in pts}
    inner=next(v for v in colors if v!=grid[r0][c0])
    # Detect the contiguous monochrome rectangle's bounding box; fill a
    # one-cell border immediately outside it with its unique interior color.
    for r in range(max(0,r0-1),min(len(grid),r1+2)):
        for c in range(max(0,c0-1),min(len(grid[0]),c1+2)):
            if r<r0 or r>r1 or c<c0 or c>c1: out[r][c]=inner
